#!/usr/bin/env node
/**
 * Enforces the project rules that can be checked statically.
 *
 * A rule that a script can verify should be a check, not a paragraph: it costs no
 * context tokens, it fires every time, and it cannot be talked out of its verdict.
 * Each check below names the rule file it enforces.
 *
 * Existing violations are recorded in .rules-lint-baseline.json and do not fail the
 * run — the baseline is a ratchet. A new violation, or more violations in an already
 * listed file, fails. Fewer violations pass and suggest refreshing the baseline.
 *
 * Usage:
 *   npm run rules:lint
 *   npm run rules:lint -- --update-baseline
 */
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { execFileSync } from 'node:child_process';

const BASELINE = '.rules-lint-baseline.json';
const updating = process.argv.includes('--update-baseline');

// Tracked and new (untracked, not ignored) files: a new spec is checked before its first commit.
const files = execFileSync('git', ['ls-files', '--cached', '--others', '--exclude-standard', '*.ts'], { encoding: 'utf8' })
  .split('\n')
  .filter(Boolean);

const read = (f) => {
  try {
    return readFileSync(f, 'utf8');
  } catch {
    return '';
  }
};

const under = (f, ...prefixes) => prefixes.some((p) => f.startsWith(p));

/**
 * Each check returns a Map of file -> number (violation count, or a size for pom-size).
 * `rule` points at the rule file in .claude/rules/ that states the invariant in prose.
 */
const CHECKS = [
  {
    id: 'no-expect-in-regression-specs',
    rule: 'playwright-specs-no-expect.md',
    hint: 'move the assertion into a should* method on the POM or a helper',
    run: () => {
      const out = new Map();
      for (const f of files) {
        if (!under(f, 'tests/specs/regression/') || !f.endsWith('.spec.ts')) continue;
        const n = (read(f).match(/\bexpect\s*\(/g) ?? []).length;
        if (n) out.set(f, n);
      }
      return out;
    },
  },
  {
    id: 'no-hardcoded-waits',
    rule: 'no-hardcoded-waits.md',
    hint: 'use a locator wait, toPass(), or a should* method instead',
    run: () => {
      const out = new Map();
      const re = /waitForTimeout\s*\(|this\.wait\s*\(|waitUntil:\s*['"]networkidle['"]/g;
      for (const f of files) {
        if (!under(f, 'page-objects/', 'tests/', 'utils/')) continue;
        const n = (read(f).match(re) ?? []).length;
        if (n) out.set(f, n);
      }
      return out;
    },
  },
  {
    id: 'pom-size',
    rule: 'page-object-size.md',
    hint: 'split the page object into components under components/',
    limit: 300,
    run: () => {
      const out = new Map();
      for (const f of files) {
        if (!under(f, 'page-objects/')) continue;
        const lines = read(f).split('\n').length;
        if (lines > 300) out.set(f, lines);
      }
      return out;
    },
  },
  {
    id: 'no-tc-ids-in-names',
    rule: 'test-naming-no-tc-ids.md',
    hint: "link the case with the annotation { type: 'test-case', description: 'TC-NN' } instead of naming it",
    run: () => {
      const out = new Map();
      const inTitle = /\b(?:test|describe)\s*\(\s*[`'"][^`'"]*\bTC-\d+/gi;
      for (const f of files) {
        if (!under(f, 'tests/')) continue;
        let n = /(^|\/)tc-\d+/i.test(f) ? 1 : 0;
        n += (read(f).match(inTitle) ?? []).length;
        if (n) out.set(f, n);
      }
      return out;
    },
  },
  {
    id: 'no-relative-imports',
    rule: 'api-test.md',
    hint: "use the @/ path alias",
    run: () => {
      const out = new Map();
      for (const f of files) {
        if (!under(f, 'tests/', 'page-objects/')) continue;
        const n = (read(f).match(/from\s+['"]\.\.\//g) ?? []).length;
        if (n) out.set(f, n);
      }
      return out;
    },
  },
  {
    id: 'no-hardcoded-endpoints',
    rule: 'api-test.md',
    hint: 'use a constant from utils/constants/routes.ts',
    run: () => {
      const out = new Map();
      for (const f of files) {
        if (!under(f, 'tests/')) continue;
        const n = (read(f).match(/['"`]\/(api|rest)\//g) ?? []).length;
        if (n) out.set(f, n);
      }
      return out;
    },
  },
  {
    id: 'seconds-to-ms-max-30',
    rule: 'date-helper-seconds-to-ms.md',
    hint: 'DateHelper.secondsToMs(n) — n must be ≤ 30; use minutesToMs for longer waits',
    run: () => {
      const out = new Map();
      const re = /secondsToMs\(\s*(\d+)\s*\)/g;
      for (const f of files) {
        if (f === 'utils/helpers/date-helper.ts') continue;
        const text = read(f);
        let n = 0;
        for (const match of text.matchAll(re)) {
          if (Number(match[1]) > 30) n += 1;
        }
        if (n) out.set(f, n);
      }
      return out;
    },
  },
];

const results = new Map(CHECKS.map((c) => [c.id, c.run()]));

if (updating) {
  const baseline = {};
  for (const [id, hits] of results) {
    if (hits.size) baseline[id] = Object.fromEntries([...hits].sort());
  }
  writeFileSync(BASELINE, `${JSON.stringify(baseline, null, 2)}\n`);
  const total = [...results.values()].reduce((a, m) => a + m.size, 0);
  console.log(`Baseline written to ${BASELINE}: ${total} file(s) recorded.`);
  process.exit(0);
}

const baseline = existsSync(BASELINE) ? JSON.parse(readFileSync(BASELINE, 'utf8')) : {};
let failures = 0;
let improved = 0;

for (const check of CHECKS) {
  const hits = results.get(check.id);
  const known = baseline[check.id] ?? {};
  const isNew = [];
  const worse = [];

  for (const [file, count] of hits) {
    const before = known[file];
    if (before === undefined) isNew.push([file, count]);
    else if (count > before) worse.push([file, count, before]);
  }
  for (const [file, before] of Object.entries(known)) {
    const now = hits.get(file);
    if (now === undefined || now < before) improved += 1;
  }

  const bad = isNew.length + worse.length;
  failures += bad;
  const label = check.limit ? `${check.id} (limit ${check.limit})` : check.id;
  console.log(
    `${bad ? '✗' : '✓'} ${label.padEnd(34)} ${String(hits.size).padStart(3)} file(s), ` +
      `${Object.keys(known).length} in baseline`,
  );
  for (const [file, count] of isNew) console.log(`    NEW    ${file} (${count})`);
  for (const [file, count, before] of worse) console.log(`    WORSE  ${file} (${before} → ${count})`);
  if (bad) console.log(`    rule: ${check.rule} — ${check.hint}`);
}

if (improved) {
  console.log(`\n${improved} baseline entr(ies) improved. Refresh with: npm run rules:lint -- --update-baseline`);
}
console.log(failures === 0 ? '\nNo new rule violations.' : `\nNew rule violations: ${failures}`);
process.exit(failures === 0 ? 0 : 1);
---
name: spec-reviewer
description: >-
  Independent read-only reviewer of a Playwright regression spec against its test case and the
  project rules. Use it after someone writes or changes a spec, before anyone calls it done. Give it
  the spec path and the test case file in test-cases/ (or the TC text). It builds expectations from
  the test case first, then reads the code. It returns a coverage matrix, rule violations with
  path:line, and a verdict ACCEPT / CHANGES / REJECT. It never edits files.
tools: Read, Grep, Glob
model: sonnet
---

You review autotests that another agent wrote. You did not write this code. You owe it nothing.
Your job is to find what is missing or wrong, not to agree that it looks fine.

You work in read-only mode. Never edit, create or delete a file. Never change a test case in `test-cases/`.

## Input

- the spec path
- the test case: a file in `test-cases/` (for example `test-cases/TC-NN-<name>.md`) or its text.
  Read `test-cases/README.md` too: it holds the shared test data. If you get neither the file nor
  the text, report that the test case is missing. Then stop.

## Procedure — in this order

### 1. Expectations first, before you open the spec

Use only the test case. For every step, write what the user does, and **every** observable
outcome in the expected result. A list of three prices is three outcomes, not one. Do this before
you read any code, so that the code cannot shape what you expect.

### 2. Read the code

Read the spec. Then read every POM method, helper and fixture that it calls, down to the assertion
that actually runs. A method's name is a claim. Its body is the evidence. If `shouldSeeSummary()`
checks two lines, it covers two outcomes.

### 3. Coverage matrix

| TC step | Expected outcome | Covered by (`file:line` of the assertion) | Verdict |
|---|---|---|---|

Verdict per row: **covered** / **partial** (checked weaker than stated, e.g. "visible" instead of
"shows the price of the selected delivery") / **missing**.

### 4. Rules

Check the spec and the code that it added against the project rules. Read the rule files. Do not
work from memory. These rules in `.claude/rules/` matter most:

- `playwright-specs-no-expect.md` — no `expect` in `.spec.ts`. Assertions live in `should*` methods
- `no-hardcoded-waits.md`, `date-helper-seconds-to-ms.md` — no `waitForTimeout`, no bare ms literals
- `test-naming-no-tc-ids.md` — no TC id in file or test names. Step names start with the TC step number. The `test-case` annotation links the TC
- `autotest-tags.md` — a tag from the dictionary
- `test-user-lifecycle.md` — a new customer for each test that needs a customer account
- `page-object-size.md`, `page-objects-conventions.md` — for new POM code
- `juice-shop-app.md` — the facts about the test app

For each violation, give the rule file, `path:line`, the offending code, and one sentence that says why.

### 5. Verdict

- **REJECT** — a TC step is missing, or the test cannot fail when the feature is broken
- **CHANGES** — partial coverage or rule violations
- **ACCEPT** — every outcome covered, no violations. Say explicitly that you found nothing.
  Say what you checked to reach that verdict

## Output

1. Expectations (step 1), as a list
2. Coverage matrix
3. Violations
4. Verdict, one line, and the two or three most important fixes

Every claim has a `path:line`. "Looks good" without a line reference is not a review.
