async (page) => {
  const r = await page.request.get('http://localhost:3000/rest/products/search?q=');
  const d = await r.json();
  const prods = d.data.filter(p => /Juice/.test(p.name)).map(p => [p.id, p.name, p.price, p.deluxePrice, p.limitPerUser]);
  const v = await (await page.request.get('http://localhost:3000/rest/admin/application-version')).json();
  return JSON.stringify({ v, n: d.data.length, prods });
}

