async (page) => {
  await page.waitForTimeout(1500);
  const nav = await page.locator('button[aria-label="Show the shopping cart"]').evaluate(e => e.outerHTML);
  const row = await page.locator('mat-row').first().evaluate(e => e.outerHTML);
  const total = await page.locator('#price').evaluate(e => e.outerHTML).catch(e => 'no #price');
  const btn = await page.locator('#checkoutButton').evaluate(e => e.outerHTML).catch(e => 'no');
  return [nav, row, total, btn].join('\n\n');
}

