async (page) => {
  const B = 'http://localhost:3000';
  const { auth } = globalThis.__probe;
  const h = { Authorization: 'Bearer ' + auth.token };
  const r = await page.request.post(B + '/api/BasketItems', { headers: h, data: { ProductId: 1, BasketId: auth.bid, quantity: 5 } });
  await page.reload();
  const row = page.locator('mat-row').filter({ hasText: 'Apple Juice' });
  await row.waitFor();
  await row.locator('button').nth(1).click();
  const snack = page.locator('simple-snack-bar, .mat-mdc-snack-bar-label, mat-snack-bar-container');
  await snack.first().waitFor({ timeout: 5000 }).catch(() => {});
  const s = await snack.allInnerTexts();
