import { encode } from 'z85';

/**
 * Coupon codes of Juice Shop: the Z85 encoding of `<MMM><YY>-<NN>` (test-cases/README.md).
 * The server checks the month in its local time, and the tests run on the same machine.
 */
const MONTHS = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'];

function couponCodeFor(month: Date, discountPercent: number): string {
  const year = String(month.getFullYear()).slice(-2);
  const percent = String(discountPercent).padStart(2, '0');
  const code = encode(`${MONTHS[month.getMonth()]}${year}-${percent}`);
  if (!code) throw new Error(`Cannot encode a coupon for ${month.toDateString()}`);
  return code;
}

export class CouponHelper {
  static currentMonthCoupon(discountPercent: number): string {
    return couponCodeFor(new Date(), discountPercent);
  }

  static previousMonthCoupon(discountPercent: number): string {
    const now = new Date();
    return couponCodeFor(new Date(now.getFullYear(), now.getMonth() - 1, 1), discountPercent);
  }
}

