import type { BasketLine, DeliveryMethod, OrderTotals } from '@/utils/types/shop';

const CURRENCY_SIGN = '¤';
const CENTS = 100;
const BONUS_POINT_DIVISOR = 10;

const roundToCents = (value: number): number => Math.round(value * CENTS) / CENTS;

export class PriceHelper {
  /** `8.99` → `8.99¤`, as the shop shows prices. */
  static format(value: number): string {
    return `${value.toFixed(2)}${CURRENCY_SIGN}`;
  }

  static itemsTotal(lines: BasketLine[]): number {
    return roundToCents(lines.reduce((sum, line) => sum + line.product.price * line.quantity, 0));
  }

  static itemCount(lines: BasketLine[]): number {
    return lines.reduce((sum, line) => sum + line.quantity, 0);
  }

  /** The coupon discount applies to the products only, not to the delivery. */
  static orderTotals(lines: BasketLine[], delivery: DeliveryMethod, discountPercent = 0): OrderTotals {
    const items = PriceHelper.itemsTotal(lines);
    const promotion = roundToCents((items * discountPercent) / CENTS);
    return { items, delivery: delivery.price, promotion, total: roundToCents(items + delivery.price - promotion) };
  }

  /** Bonus points of one product: price / 10, rounded to a whole number, × quantity. */
  static bonusPoints(lines: BasketLine[]): number {
    return lines.reduce((sum, line) => sum + Math.round(line.product.price / BONUS_POINT_DIVISOR) * line.quantity, 0);
  }
}

