import { expect, type APIRequestContext, type APIResponse } from '@playwright/test';

/** Base for the API clients: JSON calls with a status check and an optional customer token. */
export abstract class ApiClient {
  constructor(protected readonly request: APIRequestContext) {}

  protected async send<T = unknown>(
    method: 'GET' | 'POST' | 'PUT',
    path: string,
    options: { data?: unknown; token?: string; expectedStatus: number },
  ): Promise<T> {
    const response: APIResponse = await this.request.fetch(path, {
      method,
      data: options.data,
      headers: options.token ? { Authorization: `Bearer ${options.token}` } : undefined,
    });
    expect(response.status(), `${method} ${path} → ${await response.text()}`).toBe(options.expectedStatus);
    return (await response.json()) as T;
  }
}

