  async findProductId(name: string): Promise<number> {
    const body = await this.send<SearchResponse>('GET', `${API_ROUTES.productSearch}?q=${encodeURIComponent(name)}`, {
      expectedStatus: HTTP_OK,
    });
    const product = body.data.find((p) => p.name === name);
    if (!product) throw new Error(`Product "${name}" is not in the catalog`);
    return product.id;
  }
}

