export class PaymentApi extends ApiClient {
  async saveAddress(customer: CustomerSession, address: SavedAddress): Promise<void> {
    await this.send('POST', API_ROUTES.addresses, { token: customer.token, data: address, expectedStatus: HTTP_CREATED });
  }

  /** Returns the id of the saved card. */
  async saveCard(customer: CustomerSession, card: SavedCard): Promise<number> {
    const body = await this.send<CreatedResponse>('POST', API_ROUTES.cards, {
      token: customer.token,
      data: card,
      expectedStatus: HTTP_CREATED,
    });
    return body.data.id;
  }

