  async topUpWallet(customer: CustomerSession, amount: number, cardId: number): Promise<void> {
    await this.send('PUT', API_ROUTES.walletBalance, {
      token: customer.token,
      data: { balance: amount, paymentId: cardId },
      expectedStatus: HTTP_OK,
    });
  }
}

