import type { Locator, Page } from '@playwright/test';
import {
  expectHidden,
  expectStaysHidden,
  expectText,
  expectVisible,
} from '@/utils/assertions/ui-assertions';

/** The top bar: the basket button with its counter and the account menu. */
export class NavbarComponent {
  private readonly basketButton: Locator;
  private readonly basketCounter: Locator;
  private readonly accountButton: Locator;
  private readonly accountMenu: Locator;
  private readonly loginItem: Locator;
  private readonly logoutItem: Locator;
  private readonly profileItem: Locator;
  private readonly ordersAndPaymentItem: Locator;
  private readonly orderHistoryItem: Locator;
  private readonly digitalWalletItem: Locator;

  constructor(private readonly page: Page) {
    this.basketButton = page.getByRole('button', { name: 'Show the shopping cart' });
    this.basketCounter = this.basketButton.locator('.fa-layers-counter');
    this.accountButton = page.getByRole('button', { name: 'Show/hide account menu' });
    this.accountMenu = page.getByRole('menu').first();
    this.loginItem = page.getByRole('menuitem', { name: 'Go to login page' });
    this.logoutItem = page.getByRole('menuitem', { name: 'Logout' });
    this.profileItem = page.getByRole('menuitem', { name: 'Go to user profile' });
    this.ordersAndPaymentItem = page.getByRole('menuitem', { name: 'Show Orders and Payment Menu' });
    this.orderHistoryItem = page.getByRole('menuitem', { name: 'Go to order history page' });
    this.digitalWalletItem = page.getByRole('menuitem', { name: 'Go to wallet page' });
  }

  async shouldSeeLoggedInCustomer(): Promise<void> {
    await expectVisible(this.basketButton, 'Button `Your Basket`');
  }

  async shouldSeeBasketCounter(count: number): Promise<void> {
    await expectText(this.basketCounter, String(count), 'Basket counter');
  }

  async clickYourBasket(): Promise<void> {
    await this.basketButton.click();
  }

  async openAccountMenu(): Promise<void> {
    await this.accountButton.click();
    await expectVisible(this.accountMenu, 'Account menu');
  }

  async closeAccountMenu(): Promise<void> {
    await this.page.keyboard.press('Escape');
    await expectHidden(this.accountMenu, 'Account menu');
  }

  async shouldSeeLoginItem(): Promise<void> {
    await expectText(this.loginItem, /Login/, 'Account menu item `Login`');
  }

  async shouldNotSeeAccountEmail(email: string): Promise<void> {
    await expectStaysHidden(this.accountMenu.getByText(email), 'Customer email in the account menu');
  }

  async shouldSeeAccountEmail(email: string): Promise<void> {
    await expectText(this.profileItem, new RegExp(email.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')), 'Customer email in the account menu');
  }

  async shouldSeeLogoutItem(): Promise<void> {
    await expectText(this.logoutItem, /Logout/, 'Account menu item `Logout`');
  }

  async openOrderHistory(): Promise<void> {
    await this.openAccountMenu();
    await this.ordersAndPaymentItem.click();
    await this.orderHistoryItem.click();
  }

  async openDigitalWallet(): Promise<void> {
    await this.openAccountMenu();
    await this.ordersAndPaymentItem.click();
    await this.digitalWalletItem.click();
  }
}

