import type { Locator, Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { expectText, expectUrl, expectVisible } from '@/utils/assertions/ui-assertions';
import { UI_ROUTES } from '@/utils/constants/routes';
import { UI_MESSAGES, UI_TITLES } from '@/utils/constants/ui-messages';
import type { CustomerSession } from '@/utils/types/shop';

const LOGIN_URL = /#\/login$/;

export class LoginPage extends BasePage {
  private readonly title: Locator;
  private readonly emailInput: Locator;
  private readonly passwordInput: Locator;
  private readonly emailLabel: Locator;
  private readonly passwordLabel: Locator;
  private readonly loginButton: Locator;
  private readonly errorMessage: Locator;

  constructor(page: Page) {
    super(page);
    const form = page.locator('app-login');
    this.title = form.locator('h1');
    this.emailInput = form.locator('#email');
    this.passwordInput = form.locator('#password');
    this.emailLabel = form.locator('mat-label', { hasText: 'Email' });
    this.passwordLabel = form.locator('mat-label', { hasText: 'Password' });
    this.loginButton = form.locator('#loginButton');
    this.errorMessage = form.locator('.error');
  }

  async open(): Promise<void> {
    await this.openRoute(UI_ROUTES.login);
  }

  /**
   * Puts the API session into the browser the way login.component.ts does:
   * `token` in localStorage and in a cookie, the basket id `bid` in sessionStorage.
   */
  async authenticate(customer: CustomerSession): Promise<void> {
    await this.openRoute(UI_ROUTES.home);
    await this.page.evaluate(({ token, basketId }) => {
      localStorage.setItem('token', token);
      sessionStorage.setItem('bid', String(basketId));
      document.cookie = `token=${token}; path=/`;
    }, customer);
    await this.page.reload({ waitUntil: 'domcontentloaded' });
    await this.navbar.shouldSeeLoggedInCustomer();
  }

  async login(email: string, password: string): Promise<void> {
    await this.emailInput.fill(email);
    await this.passwordInput.fill(password);
    await this.loginButton.click();
  }

  async shouldSeePage(): Promise<void> {
    await expectText(this.title, UI_TITLES.login, 'Login page title');
    await expectVisible(this.emailLabel, 'Field `Email`');
    await expectVisible(this.emailInput, 'Input `Email`');
    await expectVisible(this.passwordLabel, 'Field `Password`');
    await expectVisible(this.passwordInput, 'Input `Password`');
    await expectText(this.loginButton, /Log in/, 'Button `Log in`');
  }

  async shouldSeeInvalidCredentialsError(): Promise<void> {
    await expectText(this.errorMessage, UI_MESSAGES.invalidLogin, 'Login error message');
  }

  async shouldStayOnLoginPage(): Promise<void> {
    await expectUrl(this.title, LOGIN_URL, 'Login page');
    await expectVisible(this.loginButton, 'Button `Log in`');
  }
}

