  private readonly emailInput: Locator;
  private readonly passwordInput: Locator;
  private readonly emailLabel: Locator;
  private readonly passwordLabel: Locator;
  private readonly loginButton: Locator;
  private readonly errorMessage: Locator;

  constructor(page: Page) {
    super(page);
    const form = page.locator('app-login');
    this.title = form.locator('h1');
    this.emailInput = form.locator('#email');
    this.passwordInput = form.locator('#password');
    this.emailLabel = form.locator('mat-label', { hasText: 'Email' });
