import type { Locator, Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import {
  expectCount,
  expectDisabled,
  expectHidden,
  expectText,
  expectUrl,
  expectVisible,
} from '@/utils/assertions/ui-assertions';
import { API_URL_PATTERNS, UI_ROUTES } from '@/utils/constants/routes';
import { PriceHelper } from '@/utils/helpers/price-helper';
import type { BasketLine, Product } from '@/utils/types/shop';

const BASKET_URL = /#\/basket$/;

export class BasketPage extends BasePage {
  private readonly title: Locator;
  private readonly rows: Locator;
  private readonly totalPrice: Locator;
  private readonly checkoutButton: Locator;

  constructor(page: Page) {
    super(page);
    const basket = page.locator('app-basket');
    this.title = basket.getByRole('heading', { name: /Your Basket/ });
    this.rows = basket.locator('mat-row');
    this.totalPrice = basket.locator('#price');
    this.checkoutButton = basket.locator('#checkoutButton');
  }

  private row(product: Product): Locator {
    return this.rows.filter({
      has: this.page.locator('.mat-column-product').getByText(product.name, { exact: true }),
    });
  }

  private quantityCell(product: Product): Locator {
    return this.row(product).locator('.mat-column-quantity');
  }

  /** Clicks a quantity button and waits for the server answer, so that the next check sees the result. */
  private async clickQuantityButton(button: Locator): Promise<void> {
    const update = this.page.waitForResponse(
      (response) => response.request().method() === 'PUT' && API_URL_PATTERNS.basketItem.test(response.url()),
    );
    await button.click();
    await update;
  }

  async open(): Promise<void> {
    await this.openRoute(UI_ROUTES.basket);
    await this.shouldSeePage();
  }

  async shouldSeePage(): Promise<void> {
    await expectUrl(this.title, BASKET_URL, 'Basket page');
    await expectVisible(this.title, 'Basket title');
  }

  async shouldSeeRowCount(count: number): Promise<void> {
    await expectCount(this.rows, count, 'Basket rows');
  }

  async shouldSeeLine(line: BasketLine): Promise<void> {
    const row = this.row(line.product);
    await expectVisible(row, `Basket row of ${line.product.name}`);
    await expectText(this.quantityCell(line.product), String(line.quantity), `Quantity of ${line.product.name}`);
    await expectText(row.locator('.mat-column-price'), PriceHelper.format(line.product.price), `Price of ${line.product.name}`);
  }

  async shouldNotSeeProduct(product: Product): Promise<void> {
    await expectHidden(this.row(product), `Basket row of ${product.name}`);
  }

  async shouldSeeTotalPrice(total: number): Promise<void> {
    await expectText(this.totalPrice, `Total Price: ${PriceHelper.format(total)}`, 'Basket total price');
  }

  async shouldSeeCheckoutDisabled(): Promise<void> {
    await expectDisabled(this.checkoutButton, 'Button `Checkout`');
  }

  async clickIncreaseQuantity(product: Product): Promise<void> {
    await this.clickQuantityButton(this.quantityCell(product).getByRole('button').last());
  }

  async clickDecreaseQuantity(product: Product): Promise<void> {
    await this.clickQuantityButton(this.quantityCell(product).getByRole('button').first());
  }

  async clickRemove(product: Product): Promise<void> {
    await this.row(product).locator('.mat-column-remove').getByRole('button').click();
  }

  async clickCheckout(): Promise<void> {
    await this.checkoutButton.click();
  }
}

