/** Checkout step `Select an address`. */
export class AddressSelectPage extends BasePage {
  private readonly title: Locator;
  private readonly rows: Locator;
  private readonly continueButton: Locator;

  constructor(page: Page) {
    super(page);
    const card = page.locator('app-address');
    this.title = card.locator('h1');
    this.rows = card.locator('mat-row');
    this.continueButton = card.getByRole('button', { name: 'Proceed to payment selection' });
  }

  private addressRow(address: SavedAddress): Locator {
    return this.rows.filter({ hasText: address.streetAddress });
  }

  async shouldSeePage(): Promise<void> {
    await expectText(this.title, UI_TITLES.selectAddress, 'Address step title');
