import type { Locator, Page } from '@playwright/test';
import { expectStaysHidden, expectText, expectVisible } from '@/utils/assertions/ui-assertions';
import { API_URL_PATTERNS } from '@/utils/constants/routes';
import { UI_MESSAGES, UI_TITLES } from '@/utils/constants/ui-messages';

/** The panel `Add a coupon` on the payment step. */
export class CouponPanelComponent {
  private readonly header: Locator;
  private readonly couponInput: Locator;
  private readonly redeemButton: Locator;
  private readonly confirmation: Locator;
  private readonly error: Locator;

  constructor(private readonly page: Page) {
    const panel = page.locator('#collapseCouponElement');
    this.header = panel.locator('mat-expansion-panel-header');
    this.couponInput = panel.locator('#coupon');
    this.redeemButton = panel.locator('#applyCouponButton');
    this.confirmation = page.locator('app-payment .message-spacing.confirmation');
    this.error = page.locator('app-payment .message-spacing.error');
  }

  async shouldSeePanel(): Promise<void> {
    await expectText(this.header.locator('mat-panel-title'), UI_TITLES.addCoupon, 'Panel `Add a coupon`');
  }

  async open(): Promise<void> {
    await this.header.click();
    await expectVisible(this.couponInput, 'Field `Coupon`');
  }

  /** Types the code, clicks `Redeem` and waits for the server answer about the coupon. */
  async redeemCoupon(code: string): Promise<void> {
    await this.couponInput.fill(code);
    const answer = this.page.waitForResponse((response) => API_URL_PATTERNS.basketCoupon.test(response.url()));
    await this.redeemButton.click();
    await answer;
  }

  async shouldSeeCouponAccepted(discountPercent: number): Promise<void> {
    await expectText(this.confirmation, UI_MESSAGES.couponAccepted(discountPercent), 'Coupon discount message');
  }

  async shouldSeeCouponRejected(): Promise<void> {
    await expectText(this.error, UI_MESSAGES.invalidCoupon, 'Coupon error message');
  }

  async shouldNotSeeDiscountMessage(): Promise<void> {
    await expectStaysHidden(this.confirmation, 'Coupon discount message');
  }
}

