import type { Locator, Page } from '@playwright/test';
import { expectText, expectVisible } from '@/utils/assertions/ui-assertions';
import type { SavedCard } from '@/utils/types/shop';

const VISIBLE_CARD_DIGITS = 4;
const CARD_NUMBER_MASK = '************';

export const lastCardDigits = (card: SavedCard): string => String(card.cardNum).slice(-VISIBLE_CARD_DIGITS);

/** The list of saved cards on the payment step. */
export class SavedCardsComponent {
  private readonly rows: Locator;

  constructor(page: Page) {
    this.rows = page.locator('app-payment-method mat-row');
  }

  private cardRow(card: SavedCard): Locator {
    return this.rows.filter({ hasText: `${CARD_NUMBER_MASK}${lastCardDigits(card)}` });
  }

  async shouldSeeSavedCard(card: SavedCard): Promise<void> {
    const row = this.cardRow(card);
    await expectVisible(row, 'Saved card row');
    const cells = row.locator('mat-cell');
    await expectText(cells.nth(1), `${CARD_NUMBER_MASK}${lastCardDigits(card)}`, 'Card number');
    await expectText(cells.nth(2), card.fullName, 'Card holder');
    await expectText(cells.nth(3), `${card.expMonth}/${card.expYear}`, 'Card expiry');
  }

  async selectSavedCard(card: SavedCard): Promise<void> {
    await this.cardRow(card).locator('mat-radio-button').click();
  }
}

