import type { Locator, Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { lastCardDigits } from '@/page-objects/components/saved-cards.component';
import { expectContainText, expectText } from '@/utils/assertions/ui-assertions';
import { UI_TITLES } from '@/utils/constants/ui-messages';
import { PriceHelper } from '@/utils/helpers/price-helper';
import type { OrderTotals, SavedAddress, SavedCard } from '@/utils/types/shop';

const WALLET_PAYMENT_METHOD = 'Digital Wallet';

/** Checkout step `Order Summary`, before the order is placed. */
export class OrderSummaryPage extends BasePage {
  private readonly title: Locator;
  private readonly addressCard: Locator;
  private readonly paymentCard: Locator;
  private readonly totalsRows: Locator;
  private readonly placeOrderButton: Locator;

  constructor(page: Page) {
    super(page);
    const summary = page.locator('app-order-summary');
    this.title = summary.locator('.order-summary');
    this.addressCard = summary.locator('mat-card mat-card').filter({ hasText: 'Delivery Address' });
    this.paymentCard = summary.locator('mat-card mat-card').filter({ hasText: 'Payment Method' });
    this.totalsRows = summary.locator('table tr');
    this.placeOrderButton = summary.getByRole('button', { name: 'Complete your purchase' });
  }

  private totalsRow(label: string): Locator {
    return this.totalsRows.filter({ has: this.page.locator('td.label').getByText(label, { exact: true }) });
  }

  async shouldSeePage(): Promise<void> {
    await expectText(this.title, UI_TITLES.orderSummary, 'Order summary title');
  }

  async shouldSeeDeliveryAddress(address: SavedAddress): Promise<void> {
    await expectContainText(this.addressCard, address.fullName, 'Delivery address name');
    await expectContainText(
      this.addressCard,
      `${address.streetAddress}, ${address.city}, ${address.state}, ${address.zipCode}`,
      'Delivery address line',
    );
    await expectContainText(this.addressCard, address.country, 'Delivery address country');
  }

  async shouldSeePaymentCard(card: SavedCard): Promise<void> {
    await expectContainText(this.paymentCard, `Card ending in ${lastCardDigits(card)}`, 'Payment card');
    await expectContainText(this.paymentCard, card.fullName, 'Payment card holder');
  }

  async shouldSeeWalletPaymentMethod(): Promise<void> {
    await expectContainText(this.paymentCard, WALLET_PAYMENT_METHOD, 'Payment method');
  }

  async shouldSeeTotals(totals: OrderTotals): Promise<void> {
    await expectText(this.totalsRow('Items').locator('td.price'), PriceHelper.format(totals.items), 'Items price');
    await expectText(this.totalsRow('Delivery').locator('td.price'), PriceHelper.format(totals.delivery), 'Delivery price');
    await expectText(this.totalsRow('Promotion').locator('td.price'), PriceHelper.format(totals.promotion), 'Promotion');
    await expectText(this.totalsRow('Total Price').locator('td.price'), PriceHelper.format(totals.total), 'Total price');
  }

  async clickPlaceOrder(): Promise<void> {
    await this.placeOrderButton.click();
  }
}

