import type { Locator, Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { expectText, expectUrl, expectVisible } from '@/utils/assertions/ui-assertions';
import { UI_MESSAGES } from '@/utils/constants/ui-messages';
import { PriceHelper } from '@/utils/helpers/price-helper';
import type { BasketLine, OrderTotals } from '@/utils/types/shop';

const ORDER_COMPLETION_URL = /#\/order-completion\/([\w-]+)$/;
const TOTALS_ORDER = ['items', 'delivery', 'promotion', 'total'] as const;

/** The confirmation page `/#/order-completion/<order ID>`. */
export class OrderCompletionPage extends BasePage {
  private readonly confirmation: Locator;
  private readonly productRows: Locator;
  private readonly totalsPrices: Locator;

  constructor(page: Page) {
    super(page);
    const completion = page.locator('app-order-completion');
    this.confirmation = completion.locator('h1.confirmation');
    this.productRows = completion.locator('mat-row');
    this.totalsPrices = completion.locator('mat-footer-cell.mat-column-total-price tr');
  }

  async shouldSeePage(): Promise<void> {
    await expectUrl(this.confirmation, ORDER_COMPLETION_URL, 'Order confirmation page');
  }

  async readOrderId(): Promise<string> {
    await this.shouldSeePage();
    const match = ORDER_COMPLETION_URL.exec(this.page.url());
    if (!match) throw new Error(`No order ID in ${this.page.url()}`);
    return match[1];
  }

  async shouldSeeOrderPlacedMessage(): Promise<void> {
    await expectText(this.confirmation, UI_MESSAGES.orderPlaced, 'Order confirmation message');
  }

  async shouldSeeProductLine(line: BasketLine): Promise<void> {
    const row = this.productRows.filter({ hasText: line.product.name });
    await expectVisible(row, `Order row of ${line.product.name}`);
    await expectText(row.locator('.mat-column-quantity'), String(line.quantity), `Quantity of ${line.product.name}`);
  }

  async shouldSeeTotals(totals: OrderTotals): Promise<void> {
    for (const [index, key] of TOTALS_ORDER.entries()) {
      await expectText(this.totalsPrices.nth(index), PriceHelper.format(totals[key]), `Order ${key}`);
    }
  }
}

