/**
 * Test-data setup through the API: a new customer, the saved address and card,
 * the basket contents and the wallet balance. The specs then test the UI.
 */
import type { ShopApi } from '@/core/api/shop-api';
import { CUSTOMER_EMAIL_DOMAIN, SAVED_ADDRESS, SAVED_CARD } from '@/utils/constants/test-data';
import type { BasketLine, CustomerSession } from '@/utils/types/shop';

/** A customer with a saved card can top up the wallet with it. */
export interface CustomerWithCard extends CustomerSession {
  cardId: number;
}

const uniquePart = (): string => `${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;

/** Registers a new normal (not deluxe) customer and logs it in through the API. */
export async function createCustomer(api: ShopApi): Promise<CustomerSession> {
  const unique = uniquePart();
  const customer = { email: `customer-${unique}@${CUSTOMER_EMAIL_DOMAIN}`, password: `Pw-${unique}!` };
  await api.users.register(customer);
  return api.users.login(customer);
}

/** A new customer with the saved address and the saved card of test-cases/README.md. */
export async function createCustomerWithAddressAndCard(api: ShopApi): Promise<CustomerWithCard> {
  const customer = await createCustomer(api);
  await api.payments.saveAddress(customer, SAVED_ADDRESS);
  const cardId = await api.payments.saveCard(customer, SAVED_CARD);
  return { ...customer, cardId };
}

export async function fillBasket(api: ShopApi, customer: CustomerSession, lines: BasketLine[]): Promise<void> {
  for (const line of lines) {
    const productId = await api.products.findProductId(line.product.name);
    await api.basket.addItem(customer, productId, line.quantity);
  }
}

export async function topUpWallet(api: ShopApi, customer: CustomerWithCard, amount: number): Promise<void> {
  await api.payments.topUpWallet(customer, amount, customer.cardId);
}

