import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import { PRODUCTS } from '@/utils/constants/catalog';
import { UI_MESSAGES } from '@/utils/constants/ui-messages';
import { PriceHelper } from '@/utils/helpers/price-helper';
import type { BasketLine } from '@/utils/types/shop';

const product = PRODUCTS.eggfruitJuice;
const expectedLine: BasketLine = { product, quantity: 1 };

test('Add a product to an empty basket from the product list', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.cart],
  annotation: { type: 'test-case', description: 'TC-02' },
}, async ({ customer: _customer, searchResultPage, basketPage }) => {
  await test.step('1. Open the product list', async () => {
    await searchResultPage.open();
    await searchResultPage.shouldSeeProduct(product);
    await searchResultPage.navbar.shouldSeeBasketCounter(0);
  });

  await test.step('2. Add the product to the basket', async () => {
    await searchResultPage.clickAddToBasket(product);
    await searchResultPage.snackBar.shouldSeeConfirmation(UI_MESSAGES.productPlacedInBasket(product.name));
    await searchResultPage.navbar.shouldSeeBasketCounter(expectedLine.quantity);
  });

  await test.step('3. Open the basket with the button `Your Basket`', async () => {
    await searchResultPage.navbar.clickYourBasket();
    await basketPage.shouldSeePage();
    await basketPage.shouldSeeRowCount(1);
    await basketPage.shouldSeeLine(expectedLine);
  });

  await test.step('4. Read the total of the basket', async () => {
    await basketPage.shouldSeeTotalPrice(PriceHelper.itemsTotal([expectedLine]));
  });
});

