import { test } from '@/fixtures/pages.fixture';
import { createCustomer, fillBasket } from '@/tests/helpers/customer-setup';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import { PRODUCTS } from '@/utils/constants/catalog';
import { PriceHelper } from '@/utils/helpers/price-helper';
import type { BasketLine } from '@/utils/types/shop';

const productA = PRODUCTS.raspberryJuice;
const productB = PRODUCTS.eggfruitJuice;

const basket = (quantityA: number): BasketLine[] => [
  { product: productA, quantity: quantityA },
  { product: productB, quantity: 1 },
];

test('Change the quantity of a product and remove it from the basket', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.cart],
  annotation: { type: 'test-case', description: 'TC-03' },
}, async ({ api, loginPage, basketPage }) => {
  await test.step('Precondition: a logged-in customer with product A and product B in the basket', async () => {
    const customer = await createCustomer(api);
    await fillBasket(api, customer, basket(1));
    await loginPage.authenticate(customer);
  });

  await test.step('1. Open the basket', async () => {
    await basketPage.open();
    for (const line of basket(1)) await basketPage.shouldSeeLine(line);
    await basketPage.shouldSeeTotalPrice(PriceHelper.itemsTotal(basket(1)));
    await basketPage.navbar.shouldSeeBasketCounter(PriceHelper.itemCount(basket(1)));
  });

  await test.step('2. Click the plus button of product A', async () => {
    await basketPage.clickIncreaseQuantity(productA);
    await basketPage.shouldSeeLine(basket(2)[0]);
    await basketPage.shouldSeeTotalPrice(PriceHelper.itemsTotal(basket(2)));
    await basketPage.navbar.shouldSeeBasketCounter(PriceHelper.itemCount(basket(2)));
  });

  await test.step('3. Click the minus button of product A', async () => {
    await basketPage.clickDecreaseQuantity(productA);
    await basketPage.shouldSeeLine(basket(1)[0]);
    await basketPage.shouldSeeTotalPrice(PriceHelper.itemsTotal(basket(1)));
    await basketPage.navbar.shouldSeeBasketCounter(PriceHelper.itemCount(basket(1)));
  });

  await test.step('4. Click the minus button of product A again', async () => {
    await basketPage.clickDecreaseQuantity(productA);
    await basketPage.shouldSeeLine(basket(1)[0]);
    await basketPage.shouldSeeTotalPrice(PriceHelper.itemsTotal(basket(1)));
  });

  await test.step('5. Click the trash button of product A', async () => {
    const remaining: BasketLine[] = [{ product: productB, quantity: 1 }];
    await basketPage.clickRemove(productA);
    await basketPage.shouldNotSeeProduct(productA);
    await basketPage.shouldSeeLine(remaining[0]);
    await basketPage.shouldSeeTotalPrice(PriceHelper.itemsTotal(remaining));
    await basketPage.navbar.shouldSeeBasketCounter(PriceHelper.itemCount(remaining));
  });
});

