/** UI flows of the checkout that several specs repeat: from the basket to the delivery step. */
import type { AddressSelectPage } from '@/page-objects/address-select-page';
import type { BasketPage } from '@/page-objects/basket-page';
import type { SavedAddress } from '@/utils/types/shop';

interface AddressStepPages {
  basketPage: BasketPage;
  addressSelectPage: AddressSelectPage;
}

/** Opens the basket, clicks `Checkout`, selects the saved address and clicks `Continue`. */
export async function checkoutToDeliveryStep(pages: AddressStepPages, address: SavedAddress): Promise<void> {
  await pages.basketPage.open();
  await pages.basketPage.clickCheckout();
  await pages.addressSelectPage.shouldSeePage();
  await pages.addressSelectPage.selectSavedAddress(address);
  await pages.addressSelectPage.clickContinue();
}

