input.content:
import { test } from '@/fixtures/pages.fixture';
import { createCustomerWithAddressAndCard } from '@/tests/helpers/customer-setup';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import { DELIVERY_METHODS, PRODUCTS } from '@/utils/constants/catalog';
import { COUPON, SAVED_ADDRESS, SAVED_CARD } from '@/utils/constants/test-data';
import { CouponHelper } from '@/utils/helpers/coupon-helper';
import { DateHelper } from '@/utils/helpers/date-helper';
import { PriceHelper } from '@/utils/helpers/price-helper';
import type { BasketLine } from '@/utils/types/shop';

const lineA: BasketLine = { product: PRODUCTS.eggfruitJuice, quantity: 2 };
const lineB: BasketLine = { product: PRODUCTS.carrotJuice, quantity: 1 };
const basket = [lineA, lineB];
const delivery = DELIVERY_METHODS.oneDay;
const totals = PriceHelper.orderTotals(basket, delivery, COUPON.discountPercent);

test('Order with a card and a coupon, from the basket to the order history', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.checkout],
  annotation: { type: 'test-case', description: 'TC-07' },
}, async ({
  api, loginPage, searchResultPage, basketPage, addressSelectPage, deliveryMethodPage,
  paymentPage, orderSummaryPage, orderCompletionPage, orderHistoryPage,
}) => {
  // The full checkout from the product list to the order history takes longer than the default timeout.
  test.setTimeout(DateHelper.minutesToMs(1));

  await test.step('Precondition: a logged-in customer with a saved address, a saved card and an empty basket', async () => {
    const customer = await createCustomerWithAddressAndCard(api);
    await loginPage.authenticate(customer);
  });

  await test.step('1. Add product A two times and product B one time from the product list', async () => {
    await searchResultPage.open();
    for (let added = 1; added <= lineA.quantity; added++) {
      await searchResultPage.clickAddToBasket(lineA.product);
      await searchResultPage.navbar.shouldSeeBasketCounter(added);
    }
    await searchResultPage.clickAddToBasket(lineB.product);
    await searchResultPage.navbar.shouldSeeBasketCounter(PriceHelper.itemCount(basket));
  });

  await test.step('2. Open the basket', async () => {
    await basketPage.open();
    await basketPage.shouldSeeLine(lineA);
    await basketPage.shouldSeeLine(lineB);
    await basketPage.shouldSeeTotalPrice(totals.items);
  });

  await test.step('3. Click `Checkout`, select the saved address and continue', async () => {
    await basketPage.clickCheckout();
    await addressSelectPage.selectSavedAddress(SAVED_ADDRESS);
    await addressSelectPage.clickContinue();
    await deliveryMethodPage.shouldSeePage();
  });

  await test.step(`4. Select \`${delivery.name}\` and continue`, async () => {
    await deliveryMethodPage.selectDeliveryMethod(delivery);
    await deliveryMethodPage.clickContinue();
    await paymentPage.shouldSeePage();
  });

  await test.step('5. Redeem the coupon of the current month', async () => {
    await paymentPage.openCouponPanel();
    await paymentPage.redeemCoupon(CouponHelper.currentMonthCoupon(COUPON.discountPercent));
    await paymentPage.shouldSeeCouponAccepted(COUPON.discountPercent);
  });

  await test.step('6. Select the saved card and continue', async () => {
    await paymentPage.selectSavedCard(SAVED_CARD);
    await paymentPage.clickContinue();
    await orderSummaryPage.shouldSeePage();
    await orderSummaryPage.shouldSeeDeliveryAddress(SAVED_ADDRESS);
    await orderSummaryPage.shouldSeePaymentCard(SAVED_CARD);
    await orderSummaryPage.shouldSeeTotals(totals);
  });

  const orderId = await test.step('7. Click `Place your order and pay`', async () => {
    await orderSummaryPage.clickPlaceOrder();
    await orderCompletionPage.shouldSeeOrderPlacedMessage();
    return orderCompletionPage.readOrderId();
  });

  await test.step('8. Read the order summary on the confirmation page', async () => {
    await orderCompletionPage.shouldSeeProductLine(lineA);
    await orderCompletionPage.shouldSeeProductLine(lineB);
    await orderCompletionPage.shouldSeeTotals(totals);
  });

  await test.step('9. Read the basket counter and open the basket', async () => {
    await orderCompletionPage.navbar.shouldSeeBasketCounter(0);
    await basketPage.open();
    await basketPage.shouldSeeRowCount(0);
    await basketPage.shouldSeeCheckoutDisabled();
  });

  await test.step('10. Open `Orders & Payment` → `Order History` from the account menu', async () => {
    await basketPage.navbar.openOrderHistory();
    await orderHistoryPage.shouldSeePage();
    await orderHistoryPage.shouldSeeOrderCount(1);
    await orderHistoryPage.shouldSeeOrder(orderId, totals.total);
    await orderHistoryPage.shouldSeeOrderLine(orderId, lineA);
    await orderHistoryPage.shouldSeeOrderLine(orderId, lineB);
  });
});

