import { test } from '@/fixtures/pages.fixture';
import { checkoutToDeliveryStep } from '@/tests/helpers/checkout-flows';
import {
  createCustomerWithAddressAndCard,
  fillBasket,
  topUpWallet,
  type CustomerWithCard,
} from '@/tests/helpers/customer-setup';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import { DELIVERY_METHODS, PRODUCTS } from '@/utils/constants/catalog';
import { SAVED_ADDRESS, WALLET } from '@/utils/constants/test-data';
import { DateHelper } from '@/utils/helpers/date-helper';
import { PriceHelper } from '@/utils/helpers/price-helper';
import type { BasketLine } from '@/utils/types/shop';

const basket: BasketLine[] = [{ product: PRODUCTS.eggfruitJuice, quantity: 1 }];
const delivery = DELIVERY_METHODS.standard;
const orderTotal = PriceHelper.orderTotals(basket, delivery).total;
const balanceEqualToTotal = WALLET.firstBalance + WALLET.topUpToOrderTotal;
const bonusPoints = PriceHelper.bonusPoints(basket);

test('Pay an order with the wallet only when the balance covers the total', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.wallet],
  annotation: { type: 'test-case', description: 'TC-08' },
}, async ({
  api, loginPage, basketPage, addressSelectPage, deliveryMethodPage, paymentPage,
  orderSummaryPage, orderCompletionPage, orderHistoryPage, walletPage,
}) => {
  // Two passes through the checkout, with page checks between them, take longer than the default timeout.
  test.setTimeout(DateHelper.minutesToMs(1));

  const customer: CustomerWithCard = await test.step(
    'Precondition: a logged-in customer with a saved address, a saved card, a basket and a wallet balance',
    async () => {
      const newCustomer = await createCustomerWithAddressAndCard(api);
      await fillBasket(api, newCustomer, basket);
      await topUpWallet(api, newCustomer, WALLET.firstBalance);
      await loginPage.authenticate(newCustomer);
      return newCustomer;
    },
  );

  await test.step('1. Open the basket, click `Checkout`, select the saved address and continue', async () => {
    await checkoutToDeliveryStep({ basketPage, addressSelectPage }, SAVED_ADDRESS);
    await deliveryMethodPage.shouldSeePage();
  });

  await test.step(`2. Select \`${delivery.name}\` and continue`, async () => {
    await deliveryMethodPage.selectDeliveryMethod(delivery);
    await deliveryMethodPage.clickContinue();
    await paymentPage.shouldSeePage();
    await paymentPage.shouldSeeWalletBalance(WALLET.firstBalance);
    await paymentPage.shouldSeeWalletPayButton(orderTotal);
  });

  await test.step('3. Read the wallet button `Pay`', async () => {
    await paymentPage.shouldSeeWalletPayButtonDisabled();
  });

  await test.step('4. Open `Orders & Payment` → `Order History` from the account menu', async () => {
    await paymentPage.navbar.openOrderHistory();
    await orderHistoryPage.shouldSeePage();
    await orderHistoryPage.shouldSeeNoOrdersMessage();
  });

  await test.step('5. Open `Orders & Payment` → `Digital Wallet` from the account menu', async () => {
    await orderHistoryPage.navbar.openDigitalWallet();
    await walletPage.shouldSeePage();
    await walletPage.shouldSeeBalance(WALLET.firstBalance);
  });

  await test.step('Precondition: add money to the wallet with the saved card up to the order total', async () => {
    await topUpWallet(api, customer, WALLET.topUpToOrderTotal);
  });

  await test.step(`6. Go through the checkout again with \`${delivery.name}\``, async () => {
    await checkoutToDeliveryStep({ basketPage, addressSelectPage }, SAVED_ADDRESS);
    await deliveryMethodPage.selectDeliveryMethod(delivery);
    await deliveryMethodPage.clickContinue();
    await paymentPage.shouldSeePage();
    await paymentPage.shouldSeeWalletBalance(balanceEqualToTotal);
    await paymentPage.shouldSeeWalletPayButton(orderTotal);
    await paymentPage.shouldSeeWalletPayButtonEnabled();
  });

  await test.step('7. Click the wallet button `Pay`', async () => {
    await paymentPage.clickPayWithWallet();
    await orderSummaryPage.shouldSeePage();
    await orderSummaryPage.shouldSeeWalletPaymentMethod();
    await orderSummaryPage.shouldSeeTotals(PriceHelper.orderTotals(basket, delivery));
  });

  await test.step('8. Click `Place your order and pay`', async () => {
    await orderSummaryPage.clickPlaceOrder();
    await orderCompletionPage.shouldSeeOrderPlacedMessage();
  });

  await test.step('9. Open `Orders & Payment` → `Digital Wallet` from the account menu', async () => {
    await orderCompletionPage.navbar.openDigitalWallet();
    await walletPage.shouldSeePage();
    await walletPage.shouldSeeBalance(balanceEqualToTotal - orderTotal + bonusPoints);
  });

  await test.step('10. Open `Orders & Payment` → `Order History` from the account menu', async () => {
    await walletPage.navbar.openOrderHistory();
    await orderHistoryPage.shouldSeePage();
    await orderHistoryPage.shouldSeeOrderCount(1);
    await orderHistoryPage.shouldSeeSingleOrder(orderTotal, bonusPoints);
  });
});

