5	const WRONG_PASSWORD_SUFFIX = 'x';
6	
7	test('Login with a wrong password fails and with the correct password opens the shop', {
8	  tag: [AUTOTEST_PLAYWRIGHT_TAGS.auth],
9	  annotation: { type: 'test-case', description: 'TC-01' },
10	}, async ({ api, loginPage, searchResultPage }) => {
11	  const customer = await test.step('Precondition: create a customer account, nobody is logged in', async () => {
12	    return createCustomer(api);
13	  });
14	
15	  await test.step('1. Open the login page', async () => {
16	    await loginPage.open();
17	    await loginPage.shouldSeePage();
18	  });
19	
20	  await test.step('2. Log in with the wrong password', async () => {
21	    await loginPage.login(customer.email, `${customer.password}${WRONG_PASSWORD_SUFFIX}`);
22	    await loginPage.shouldSeeInvalidCredentialsError();
23	    await loginPage.shouldStayOnLoginPage();
24	  });
25	
26	  await test.step('3. Open the account menu', async () => {
27	    await loginPage.navbar.openAccountMenu();
28	    await loginPage.navbar.shouldSeeLoginItem();
29	    await loginPage.navbar.shouldNotSeeAccountEmail(customer.email);
30	  });
31	
32	  await test.step('4. Close the menu and log in with the correct password', async () => {
