1	import type { Locator, Page } from '@playwright/test';
2	import { BasePage } from '@/page-objects/base-page';
3	import { expectText, expectUrl, expectVisible } from '@/utils/assertions/ui-assertions';
4	import { UI_ROUTES } from '@/utils/constants/routes';
5	import { UI_MESSAGES, UI_TITLES } from '@/utils/constants/ui-messages';
6	import type { CustomerSession } from '@/utils/types/shop';
7	
8	const LOGIN_URL = /#\/login$/;
9	
10	export class LoginPage extends BasePage {
11	  private readonly title: Locator;
12	  private readonly emailInput: Locator;
13	  private readonly passwordInput: Locator;
14	  private readonly emailLabel: Locator;
15	  private readonly passwordLabel: Locator;
16	  private readonly loginButton: Locator;
17	  private readonly errorMessage: Locator;
18	
19	  constructor(page: Page) {
20	    super(page);
21	    const form = page.locator('app-login');
22	    this.title = form.locator('h1');
23	    this.emailInput = form.locator('#email');
24	    this.passwordInput = form.locator('#password');
25	    this.emailLabel = form.locator('mat-label', { hasText: 'Email' });
26	    this.passwordLabel = form.locator('mat-label', { hasText: 'Password' });
27	    this.loginButton = form.locator('#loginButton');
28	    this.errorMessage = form.locator('.error');
29	  }
30	
31	  async open(): Promise<void> {
32	    await this.openRoute(UI_ROUTES.login);
33	  }
34	
35	  /**
36	   * Puts the API session into the browser the way login.component.ts does:
37	   * `token` in localStorage and in a cookie, the basket id `bid` in sessionStorage.
38	   * The init script runs before the app loads, and only once per browser tab.
39	   */
40	  async authenticate(customer: CustomerSession): Promise<void> {
41	    await this.page.addInitScript(({ token, basketId }) => {
42	      if (sessionStorage.getItem('autotestSession') === token) return;
43	      sessionStorage.setItem('autotestSession', token);
44	      localStorage.setItem('token', token);
45	      sessionStorage.setItem('bid', String(basketId));
46	      document.cookie = `token=${token}; path=/`;
47	    }, { token: customer.token, basketId: customer.basketId });
48	    await this.openRoute(UI_ROUTES.home);
49	    await this.navbar.shouldSeeLoggedInCustomer();
50	  }
51	
52	  async login(email: string, password: string): Promise<void> {
53	    await this.emailInput.fill(email);
54	    await this.passwordInput.fill(password);
55	    await this.loginButton.click();
56	  }
57	
58	  async shouldSeePage(): Promise<void> {
59	    await expectText(this.title, UI_TITLES.login, 'Login page title');
60	    await expectVisible(this.emailLabel, 'Field `Email`');
61	    await expectVisible(this.emailInput, 'Input `Email`');
62	    await expectVisible(this.passwordLabel, 'Field `Password`');
63	    await expectVisible(this.passwordInput, 'Input `Password`');
64	    await expectText(this.loginButton, /Log in/, 'Button `Log in`');
65	  }
66	
67	  async shouldSeeInvalidCredentialsError(): Promise<void> {
68	    await expectText(this.errorMessage, UI_MESSAGES.invalidLogin, 'Login error message');
69	  }
70	
71	  async shouldStayOnLoginPage(): Promise<void> {
72	    await expectUrl(this.title, LOGIN_URL, 'Login page');
73	    await expectVisible(this.loginButton, 'Button `Log in`');
74	  }
75	}
