1	import { expect, type Locator } from '@playwright/test';
2	import { DateHelper } from '@/utils/helpers/date-helper';
3	
4	/** How long an "it does not show" check watches the page. */
5	const ABSENCE_HOLD_MS = DateHelper.secondsToMs(2);
6	
7	export async function expectVisible(locator: Locator, description: string): Promise<void> {
8	  await expect(locator, `${description} is visible`).toBeVisible();
9	}
10	
11	export async function expectHidden(locator: Locator, description: string): Promise<void> {
12	  await expect(locator, `${description} is hidden`).toBeHidden();
13	}
14	
15	/** An absence needs a hold: fails if the element shows at any moment of the hold window. */
16	export async function expectStaysHidden(locator: Locator, description: string): Promise<void> {
17	  const appeared = await locator.waitFor({ state: 'visible', timeout: ABSENCE_HOLD_MS }).then(
18	    () => true,
19	    () => false,
20	  );
21	  expect(appeared, `${description} does not show`).toBe(false);
22	}
23	
24	export async function expectText(locator: Locator, text: string | RegExp, description: string): Promise<void> {
25	  await expect(locator, `${description} has text "${text}"`).toHaveText(text);
26	}
27	
28	export async function expectContainText(locator: Locator, text: string | RegExp, description: string): Promise<void> {
29	  await expect(locator, `${description} contains "${text}"`).toContainText(text);
30	}
31	
32	export async function expectCount(locator: Locator, count: number, description: string): Promise<void> {
33	  await expect(locator, `${description}: count is ${count}`).toHaveCount(count);
34	}
35	
36	export async function expectEnabled(locator: Locator, description: string): Promise<void> {
37	  await expect(locator, `${description} is enabled`).toBeEnabled();
38	}
39	
40	export async function expectDisabled(locator: Locator, description: string): Promise<void> {
41	  await expect(locator, `${description} is disabled`).toBeDisabled();
42	}
43	
44	export async function expectUrl(locator: Locator, url: RegExp, description: string): Promise<void> {
45	  await expect(locator.page(), `${description}: URL matches ${url}`).toHaveURL(url);
46	}
