1	import { test } from '@/fixtures/pages.fixture';
2	import { createCustomer, fillBasket } from '@/tests/helpers/customer-setup';
3	import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
4	import { PRODUCTS } from '@/utils/constants/catalog';
5	import { PriceHelper } from '@/utils/helpers/price-helper';
6	import type { BasketLine } from '@/utils/types/shop';
7	
8	const productA = PRODUCTS.raspberryJuice;
9	const productB = PRODUCTS.eggfruitJuice;
10	
11	const basket = (quantityA: number): BasketLine[] => [
12	  { product: productA, quantity: quantityA },
13	  { product: productB, quantity: 1 },
14	];
15	
16	test('Change the quantity of a product and remove it from the basket', {
17	  tag: [AUTOTEST_PLAYWRIGHT_TAGS.cart],
18	  annotation: { type: 'test-case', description: 'TC-03' },
19	}, async ({ api, loginPage, basketPage }) => {
20	  await test.step('Precondition: a logged-in customer with product A and product B in the basket', async () => {
21	    const customer = await createCustomer(api);
22	    await fillBasket(api, customer, basket(1));
23	    await loginPage.authenticate(customer);
24	  });
25	
26	  await test.step('1. Open the basket', async () => {
27	    await basketPage.open();
28	    for (const line of basket(1)) await basketPage.shouldSeeLine(line);
29	    await basketPage.shouldSeeTotalPrice(PriceHelper.itemsTotal(basket(1)));
30	    await basketPage.navbar.shouldSeeBasketCounter(PriceHelper.itemCount(basket(1)));
31	  });
32	
33	  await test.step('2. Click the plus button of product A', async () => {
34	    await basketPage.clickIncreaseQuantity(productA);
35	    await basketPage.shouldSeeLine(basket(2)[0]);
36	    await basketPage.shouldSeeTotalPrice(PriceHelper.itemsTotal(basket(2)));
37	    await basketPage.navbar.shouldSeeBasketCounter(PriceHelper.itemCount(basket(2)));
38	  });
39	
40	  await test.step('3. Click the minus button of product A', async () => {
41	    await basketPage.clickDecreaseQuantity(productA);
