1	import type { BasketLine, DeliveryMethod, OrderTotals } from '@/utils/types/shop';
2	
3	const CURRENCY_SIGN = '¤';
4	const CENTS = 100;
5	const BONUS_POINT_DIVISOR = 10;
6	
7	const roundToCents = (value: number): number => Math.round(value * CENTS) / CENTS;
8	
9	export class PriceHelper {
10	  /** `8.99` → `8.99¤`, as the shop shows prices. */
11	  static format(value: number): string {
12	    return `${value.toFixed(2)}${CURRENCY_SIGN}`;
13	  }
14	
15	  static itemsTotal(lines: BasketLine[]): number {
16	    return roundToCents(lines.reduce((sum, line) => sum + line.product.price * line.quantity, 0));
17	  }
18	
19	  static itemCount(lines: BasketLine[]): number {
20	    return lines.reduce((sum, line) => sum + line.quantity, 0);
21	  }
22	
23	  /** The coupon discount applies to the products only, not to the delivery. */
24	  static orderTotals(lines: BasketLine[], delivery: DeliveryMethod, discountPercent = 0): OrderTotals {
25	    const items = PriceHelper.itemsTotal(lines);
26	    const promotion = roundToCents((items * discountPercent) / CENTS);
27	    return { items, delivery: delivery.price, promotion, total: roundToCents(items + delivery.price - promotion) };
28	  }
29	
30	  /** Bonus points of one product: price / 10, rounded to a whole number, × quantity. */
31	  static bonusPoints(lines: BasketLine[]): number {
32	    return lines.reduce((sum, line) => sum + Math.round(line.product.price / BONUS_POINT_DIVISOR) * line.quantity, 0);
33	  }
34	}
