1	import { encode } from 'z85';
2	
3	/**
4	 * Coupon codes of Juice Shop: the Z85 encoding of `<MMM><YY>-<NN>` (test-cases/README.md).
5	 * The server checks the month in its local time, and the tests run on the same machine.
6	 */
7	const MONTHS = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'];
8	
9	function couponCodeFor(month: Date, discountPercent: number): string {
10	  const year = String(month.getFullYear()).slice(-2);
11	  const percent = String(discountPercent).padStart(2, '0');
12	  const code = encode(`${MONTHS[month.getMonth()]}${year}-${percent}`);
13	  if (!code) throw new Error(`Cannot encode a coupon for ${month.toDateString()}`);
14	  return code;
15	}
16	
17	export class CouponHelper {
18	  static currentMonthCoupon(discountPercent: number): string {
19	    return couponCodeFor(new Date(), discountPercent);
20	  }
21	
22	  static previousMonthCoupon(discountPercent: number): string {
23	    const now = new Date();
24	    return couponCodeFor(new Date(now.getFullYear(), now.getMonth() - 1, 1), discountPercent);
25	  }
26	}
