import { test } from '@/fixtures/customer.fixture';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import { PRODUCTS, PURCHASE_LIMIT } from '@/utils/constants/catalog';
import { UI_MESSAGES } from '@/utils/constants/ui-messages';
import { PriceHelper } from '@/utils/helpers/price-helper';
import type { BasketLine } from '@/utils/types/shop';

const product = PRODUCTS.appleJuice;
const lineAtLimit: BasketLine = { product, quantity: PURCHASE_LIMIT };

test('A basket holds no more items of a product than its purchase limit', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.cart],
  annotation: { type: 'test-case', description: 'TC-04' },
}, async ({ customer: _customer, searchResultPage, basketPage }) => {
  await test.step('1. Add the product to the basket from the product list', async () => {
    await searchResultPage.open();
    await searchResultPage.clickAddToBasket(product);
    await searchResultPage.snackBar.shouldSeeConfirmation(UI_MESSAGES.productPlacedInBasket(product.name));
    await searchResultPage.navbar.shouldSeeBasketCounter(1);
  });

  await test.step(`2. Open the basket and click plus until the quantity is ${PURCHASE_LIMIT}`, async () => {
    await basketPage.open();
    for (let quantity = 2; quantity <= PURCHASE_LIMIT; quantity++) {
      await basketPage.clickIncreaseQuantity(product);
      await basketPage.shouldSeeLine({ product, quantity });
    }
    await basketPage.shouldSeeTotalPrice(PriceHelper.itemsTotal([lineAtLimit]));
    await basketPage.snackBar.shouldNotSeeError();
  });

  await test.step('3. Click the plus button one more time', async () => {
    await basketPage.clickIncreaseQuantity(product);
    await basketPage.snackBar.shouldSeeError(UI_MESSAGES.purchaseLimitReached(PURCHASE_LIMIT));
  });

  await test.step('4. Read the basket', async () => {
    await basketPage.shouldSeeLine(lineAtLimit);
    await basketPage.shouldSeeTotalPrice(PriceHelper.itemsTotal([lineAtLimit]));
    await basketPage.navbar.shouldSeeBasketCounter(PURCHASE_LIMIT);
  });

  await test.step('5. Add the product to the basket from the product list again', async () => {
    await searchResultPage.open();
    await searchResultPage.clickAddToBasket(product);
    await searchResultPage.snackBar.shouldSeeError(UI_MESSAGES.purchaseLimitReached(PURCHASE_LIMIT));
    await searchResultPage.navbar.shouldSeeBasketCounter(PURCHASE_LIMIT);
  });
});

