import { test } from '@/fixtures/pages.fixture';
import { checkoutToDeliveryStep } from '@/tests/helpers/checkout-flows';
import { createCustomerWithAddressAndCard, fillBasket } from '@/tests/helpers/customer-setup';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import { DELIVERY_METHODS, PRODUCTS } from '@/utils/constants/catalog';
import { COUPON, SAVED_ADDRESS, SAVED_CARD } from '@/utils/constants/test-data';
import { CouponHelper } from '@/utils/helpers/coupon-helper';
import { PriceHelper } from '@/utils/helpers/price-helper';
import type { BasketLine } from '@/utils/types/shop';

const basket: BasketLine[] = [{ product: PRODUCTS.eggfruitJuice, quantity: 2 }];
const delivery = DELIVERY_METHODS.oneDay;

test('An invalid code and a coupon of the previous month give no discount', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.coupon],
  annotation: { type: 'test-case', description: 'TC-06' },
}, async ({ api, loginPage, basketPage, addressSelectPage, deliveryMethodPage, paymentPage, orderSummaryPage }) => {
  await test.step('Precondition: a logged-in customer with a saved address, a saved card and a basket', async () => {
    const customer = await createCustomerWithAddressAndCard(api);
    await fillBasket(api, customer, basket);
    await loginPage.authenticate(customer);
  });

  await test.step('1. Open the basket, click `Checkout`, select the saved address and continue', async () => {
    await checkoutToDeliveryStep({ basketPage, addressSelectPage }, SAVED_ADDRESS);
    await deliveryMethodPage.shouldSeePage();
  });

  await test.step(`2. Select \`${delivery.name}\` and continue`, async () => {
    await deliveryMethodPage.selectDeliveryMethod(delivery);
    await deliveryMethodPage.clickContinue();
    await paymentPage.shouldSeePage();
  });

  await test.step('3. Redeem the invalid code', async () => {
    await paymentPage.openCouponPanel();
    await paymentPage.redeemCoupon(COUPON.invalidCode);
    await paymentPage.shouldSeeCouponRejected();
    await paymentPage.shouldNotSeeDiscountMessage();
  });

  await test.step('4. Redeem the coupon of the previous month', async () => {
    await paymentPage.redeemCoupon(CouponHelper.previousMonthCoupon(COUPON.discountPercent));
    await paymentPage.shouldSeeCouponRejected();
    await paymentPage.shouldNotSeeDiscountMessage();
  });

  await test.step('5. Select the saved card and continue', async () => {
    await paymentPage.selectSavedCard(SAVED_CARD);
    await paymentPage.clickContinue();
    await orderSummaryPage.shouldSeePage();
    await orderSummaryPage.shouldSeeTotals(PriceHelper.orderTotals(basket, delivery));
  });
});

